// confirmed.
func (r *raft) releaseConfirmedReads() {
	for _, rs := range r.readOnly.maybeAdvance(r.trk.Voters) {
		if resp := r.responseToReadIndexReq(rs.req, rs.index); resp.GetTo() != None {
			r.send(resp)
		}
