 fs,as,bs:=newTestMemoryStorage(withPeers(1,2,3)),newTestMemoryStorage(withPeers(1,2,3)),newTestMemoryStorage(withPeers(1,2,3))
 f:=regressionNode(t,1,true,false,false,fs)
 a,b:=regressionNode(t,2,false,false,false,as),regressionNode(t,3,false,false,false,bs)
 require.NoError(t,a.Campaign());am,_:=regressionSync(t,a,as)
 require.NoError(t,b.Campaign());bm,_:=regressionSync(t,b,bs)
 av,bv:=regressionFind(am,pb.MsgVote,1),regressionFind(bm,pb.MsgVote,1)
 require.NotNil(t,av);require.NotNil(t,bv)
 require.NoError(t,f.Step(av));_=f.Ready()
 require.NoError(t,f.Step(av));rd:=f.Ready()
 for _,m:=range rd.Messages {if m.GetTo()==2 {require.NoError(t,a.Step(m))}}
 regressionSync(t,a,as)
 f=regressionNode(t,1,true,false,false,fs) // crash before either append write
 require.NoError(t,f.Step(bv));rd=f.Ready()
 for _,m:=range rd.Messages {if m.GetType()==pb.MsgStorageAppend {for _,r:=range regressionStorage(t,f,fs,m){require.NoError(t,b.Step(r))}}}
 // B commits and applies Y at index 2 with F, while A is partitioned.
 regressionPair(t,b,f,bs,fs)
 require.NoError(t,b.Propose([]byte("Y")))
 appliedB:=regressionPair(t,b,f,bs,fs)
 require.NotEmpty(t,appliedB)
 // A's same-term append is acknowledged at F's committed index, despite
 // having different data. On the repair A remains a candidate.
 err:=a.Propose([]byte("X"))
 if err==ErrProposalDropped {require.NotEqual(t,StateLeader,a.raft.state);return}
 require.NoError(t,err)
 appliedA:=regressionPair(t,a,f,as,fs)
 var x,y *pb.Entry
 for _,e:=range appliedA {if string(e.GetData())=="X" {x=e}}
 for _,e:=range appliedB {if string(e.GetData())=="Y" {y=e}}
 conflict:=x!=nil && y!=nil && x.GetIndex()==y.GetIndex()
 // B advances once more. A still answers a safe ReadIndex with its stale
 // index using a heartbeat quorum {A,F}; isolate append traffic for the read.
 require.NoError(t,b.Propose([]byte("Z")))
 later:=regressionPair(t,b,f,bs,fs);require.NotEmpty(t,later)
 high:=later[len(later)-1].GetIndex()
 a.ReadIndex([]byte("after-Z"));rd=a.Ready();regressionPersist(t,as,rd)
 for _,m:=range rd.Messages {if m.GetType()==pb.MsgHeartbeat && m.GetTo()==1 {require.NoError(t,f.Step(m))}}
 a.Advance(rd)
 for f.HasReady() {fr:=f.Ready();for _,m:=range fr.Messages {if m.GetType()==pb.MsgHeartbeatResp && m.GetTo()==2 {require.NoError(t,a.Step(m))} else if m.GetType()==pb.MsgStorageAppend {for _,r:=range regressionStorage(t,f,fs,m){if r.GetType()==pb.MsgHeartbeatResp && r.GetTo()==2 {require.NoError(t,a.Step(r))}}}}}
 rd=a.Ready();regressionPersist(t,as,rd);a.Advance(rd)
 stale:=false;for _,rs:=range rd.ReadStates {if rs.Index<high {stale=true}}
 require.False(t,conflict || stale,"different entries applied at one index: %v; stale ReadState: %v",conflict,stale)
}
